import numpy as np
from scipy.optimize import minimize_scalar
from scipy.special import gammainc, ive


# The one-sided survival probability is most conveniently represented as a
# mixture of Erlang CDFs. If x = rho*v*t, write
#
#     h(x, p) = 1 - sum_m B_m(p) P(2m+1, x),
#
# where P(n, x) is the regularized lower incomplete gamma function. The
# coefficients are generated by
#
#     u = z * (q + a*u**2 - b*u**4) = sum_m B_m z**(2m+1),
#
# with q=(1-p)/2, a=(1+2p)/2, and b=p/2. This is the exact finite-time
# one-sided survival law for the three ballistic velocities. The tagged
# particle has independent left and right factors, so its survival is h**2.
_SERIES_ORDER = 512


def _coefficients(stationary_fraction, order=_SERIES_ORDER):
    """Return the odd-power coefficients B_m for one-sided survival."""
    p = float(stationary_fraction)
    q = (1.0 - p) / 2.0
    a = (1.0 + 2.0 * p) / 2.0
    b = p / 2.0

    coefficients = np.zeros(order + 1, dtype=float)
    square = np.zeros(order + 1, dtype=float)
    coefficients[0] = q
    square[0] = q * q

    # If u=sum B_m z^(2m+1), square contains the coefficients of u**2.
    # The coefficients of u**4 are the convolution of square with itself.
    for m in range(1, order + 1):
        quartic = 0.0
        if m >= 2:
            quartic = np.dot(square[:m - 1], square[m - 2::-1])
        coefficients[m] = a * square[m - 1] - b * quartic
        square[m] = np.dot(coefficients[:m + 1], coefficients[m::-1])

    return coefficients


def _one_sided_survival(x, stationary_fraction):
    """Probability that one half-line has not sent a particle to the tag."""
    x = float(x)
    p = float(stationary_fraction)
    if x <= 0.0 or p >= 1.0:
        return 1.0

    # At p=0 this reduces to the supplied stable Bessel expression.
    if p == 0.0:
        return float(ive(0, x) + ive(1, x))

    coefficients = _coefficients(p)
    orders = 2.0 * np.arange(_SERIES_ORDER + 1) + 1.0
    # For the maximum allowed x=93.6, omitted terms have an effectively zero
    # lower-gamma factor. The form below is also stable at x=0 and p near 1.
    value = 1.0 - np.dot(coefficients, gammainc(orders, x))
    return float(np.clip(value, 0.0, 1.0))


def response(e, speed):
    x = e['density'] * speed * e['time']
    one_side = _one_sided_survival(x, e['stationary_fraction'])
    return float(one_side * one_side)


def predict_at(experiments, speed):
    return np.asarray([response(e, speed) for e in experiments], dtype=float)


class Model:
    def __init__(self):
        self.speed = None

    def fit(self, records):
        records = list(records)
        if not records:
            raise ValueError('At least one calibration record is required.')

        experiments = [record['input'] for record in records]
        values = np.asarray([record['value'] for record in records], dtype=float)
        sigmas = np.asarray([record['sigma'] for record in records], dtype=float)
        if not np.isfinite(values).all() or not np.isfinite(sigmas).all():
            raise ValueError('Calibration values and uncertainties must be finite.')
        if np.any(sigmas <= 0.0):
            raise ValueError('Calibration uncertainties must be positive.')

        def objective(speed):
            residual = (predict_at(experiments, speed) - values) / sigmas
            return float(np.dot(residual, residual))

        result = minimize_scalar(
            objective,
            bounds=(0.8, 1.3),
            method='bounded',
            options={'xatol': 1e-12},
        )
        self.speed = float(result.x)
        return self

    def predict(self, experiments):
        return predict_at(experiments, self.speed)
